Here is the commit message:
svcrdma: handle rdma read with a non-zero initial page offset

The server rdma_read_chunk_lcl() and rdma_read_chunk_frmr() functions
were not taking into account the initial page_offset when determining
the rdma read length.  This resulted in a read who's starting address
and length exceeded the base/bounds of the frmr.

The server gets an async error from the rdma device and kills the
connection, and the client then reconnects and resends.  This repeats
indefinitely, and the application hangs.

Most work loads don't tickle this bug apparently, but one test hit it
every time: building the linux kernel on a 16 core node with 'make -j
16 O=/mnt/0' where /mnt/0 is a ramdisk mounted via NFSRDMA.

This bug seems to only be tripped with devices having small fastreg page
list depths.  I didn't see it with mlx4, for instance.

Fixes: 0bf4828983df ('svcrdma: refactor marshalling logic')
Signed-off-by: Steve Wise <swise@opengridcomputing.com>
Tested-by: Chuck Lever <chuck.lever@oracle.com>
Cc: stable@vger.kernel.org
Signed-off-by: J. Bruce Fields <bfields@redhat.com>

Here is the root cause:
The bug occurs because the `rdma_read_chunk_lcl()` and `rdma_read_chunk_frmr()` functions do not properly account for the initial `page_offset` when calculating the read length. This oversight can lead to read operations that exceed the bounds of the frmr, resulting in asynchronous errors from the RDMA device, which causes the server to terminate the connection and the application to hang.

Here is the patch:
 /* Issue an RDMA_READ using the local lkey to map the data sink */
 int rdma_read_chunk_lcl(struct svcxprt_rdma *xprt,
 			struct svc_rqst *rqstp,
 			struct svc_rdma_op_ctxt *head,
 			int *page_no,
 			u32 *page_offset,
 			u32 rs_handle,
 			u32 rs_length,
 			u64 rs_offset,
 			bool last)
 {
 	struct ib_send_wr read_wr;
 	int pages_needed = PAGE_ALIGN(*page_offset + rs_length) >> PAGE_SHIFT;
 	struct svc_rdma_op_ctxt *ctxt = svc_rdma_get_context(xprt);
 	int ret, read, pno;
 	u32 pg_off = *page_offset;
 	u32 pg_no = *page_no;

 	ctxt->direction = DMA_FROM_DEVICE;
 	ctxt->read_hdr = head;
 	pages_needed = min_t(int, pages_needed, xprt->sc_max_sge_rd);
-	read = min_t(int, pages_needed << PAGE_SHIFT, rs_length);
+	read = min_t(int, (pages_needed << PAGE_SHIFT) - *page_offset,
+		     rs_length);

 	for (pno = 0; pno < pages_needed; pno++) {
 		int len = min_t(int, rs_length, PAGE_SIZE - pg_off);

 		head->arg.pages[pg_no] = rqstp->rq_arg.pages[pg_no];
 		head->arg.page_len += len;
 		head->arg.len += len;
 		if (!pg_off)
 			head->count++;
 		rqstp->rq_respages = &rqstp->rq_arg.pages[pg_no+1];
 		rqstp->rq_next_page = rqstp->rq_respages + 1;
 		ctxt->sge[pno].addr =
 			ib_dma_map_page(xprt->sc_cm_id->device,
 					head->arg.pages[pg_no], pg_off,
 					PAGE_SIZE - pg_off,
 					DMA_FROM_DEVICE);
 		ret = ib_dma_mapping_error(xprt->sc_cm_id->device,
 					   ctxt->sge[pno].addr);
 		if (ret)
 			goto err;
 		atomic_inc(&xprt->sc_dma_used);

 		/* The lkey here is either a local dma lkey or a dma_mr lkey */
 		ctxt->sge[pno].lkey = xprt->sc_dma_lkey;
 		ctxt->sge[pno].length = len;
 		ctxt->count++;

 		/* adjust offset and wrap to next page if needed */
 		pg_off += len;
 		if (pg_off == PAGE_SIZE) {
 			pg_off = 0;
 			pg_no++;
 		}
 		rs_length -= len;
 	}

 	if (last && rs_length == 0)
 		set_bit(RDMACTXT_F_LAST_CTXT, &ctxt->flags);
 	else
 		clear_bit(RDMACTXT_F_LAST_CTXT, &ctxt->flags);

 	memset(&read_wr, 0, sizeof(read_wr));
 	read_wr.wr_id = (unsigned long)ctxt;
 	read_wr.opcode = IB_WR_RDMA_READ;
 	ctxt->wr_op = read_wr.opcode;
 	read_wr.send_flags = IB_SEND_SIGNALED;
 	read_wr.wr.rdma.rkey = rs_handle;
 	read_wr.wr.rdma.remote_addr = rs_offset;
 	read_wr.sg_list = ctxt->sge;
 	read_wr.num_sge = pages_needed;

 	ret = svc_rdma_send(xprt, &read_wr);
 	if (ret) {
 		pr_err("svcrdma: Error %d posting RDMA_READ\n", ret);
 		set_bit(XPT_CLOSE, &xprt->sc_xprt.xpt_flags);
 		goto err;
 	}

 	/* return current location in page array */
 	*page_no = pg_no;
 	*page_offset = pg_off;
 	ret = read;
 	atomic_inc(&rdma_stat_read);
 	return ret;
  err:
 	svc_rdma_unmap_dma(ctxt);
 	svc_rdma_put_context(ctxt, 0);
 	return ret;
 }

 /* Issue an RDMA_READ using an FRMR to map the data sink */
 int rdma_read_chunk_frmr(struct svcxprt_rdma *xprt,
 			 struct svc_rqst *rqstp,
 			 struct svc_rdma_op_ctxt *head,
 			 int *page_no,
 			 u32 *page_offset,
 			 u32 rs_handle,
 			 u32 rs_length,
 			 u64 rs_offset,
 			 bool last)
 {
 	struct ib_send_wr read_wr;
 	struct ib_send_wr inv_wr;
 	struct ib_send_wr fastreg_wr;
 	u8 key;
 	int pages_needed = PAGE_ALIGN(*page_offset + rs_length) >> PAGE_SHIFT;
 	struct svc_rdma_op_ctxt *ctxt = svc_rdma_get_context(xprt);
 	struct svc_rdma_fastreg_mr *frmr = svc_rdma_get_frmr(xprt);
 	int ret, read, pno;
 	u32 pg_off = *page_offset;
 	u32 pg_no = *page_no;

 	if (IS_ERR(frmr))
 		return -ENOMEM;

 	ctxt->direction = DMA_FROM_DEVICE;
 	ctxt->frmr = frmr;
 	pages_needed = min_t(int, pages_needed, xprt->sc_frmr_pg_list_len);
-	read = min_t(int, pages_needed << PAGE_SHIFT, rs_length);
+	read = min_t(int, (pages_needed << PAGE_SHIFT) - *page_offset,
+		     rs_length);

 	frmr->kva = page_address(rqstp->rq_arg.pages[pg_no]);
 	frmr->direction = DMA_FROM_DEVICE;
 	frmr->access_flags = (IB_ACCESS_LOCAL_WRITE|IB_ACCESS_REMOTE_WRITE);
 	frmr->map_len = pages_needed << PAGE_SHIFT;
 	frmr->page_list_len = pages_needed;

 	for (pno = 0; pno < pages_needed; pno++) {
 		int len = min_t(int, rs_length, PAGE_SIZE - pg_off);

 		head->arg.pages[pg_no] = rqstp->rq_arg.pages[pg_no];
 		head->arg.page_len += len;
 		head->arg.len += len;
 		if (!pg_off)
 			head->count++;
 		rqstp->rq_respages = &rqstp->rq_arg.pages[pg_no+1];
 		rqstp->rq_next_page = rqstp->rq_respages + 1;
 		frmr->page_list->page_list[pno] =
 			ib_dma_map_page(xprt->sc_cm_id->device,
 					head->arg.pages[pg_no], 0,
 					PAGE_SIZE, DMA_FROM_DEVICE);
 		ret = ib_dma_mapping_error(xprt->sc_cm_id->device,
 					   frmr->page_list->page_list[pno]);
 		if (ret)
 			goto err;
 		atomic_inc(&xprt->sc_dma_used);

 		/* adjust offset and wrap to next page if needed */
 		pg_off += len;
 		if (pg_off == PAGE_SIZE) {
 			pg_off = 0;
 			pg_no++;
 		}
 		rs_length -= len;
 	}

 	if (last && rs_length == 0)
 		set_bit(RDMACTXT_F_LAST_CTXT, &ctxt->flags);
 	else
 		clear_bit(RDMACTXT_F_LAST_CTXT, &ctxt->flags);

 	/* Bump the key */
 	key = (u8)(frmr->mr->lkey & 0x000000FF);
 	ib_update_fast_reg_key(frmr->mr, ++key);

 	ctxt->sge[0].addr = (unsigned long)frmr->kva + *page_offset;
 	ctxt->sge[0].lkey = frmr->mr->lkey;
 	ctxt->sge[0].length = read;
 	ctxt->count = 1;
 	ctxt->read_hdr = head;

 	/* Prepare FASTREG WR */
 	memset(&fastreg_wr, 0, sizeof(fastreg_wr));
 	fastreg_wr.opcode = IB_WR_FAST_REG_MR;
 	fastreg_wr.send_flags = IB_SEND_SIGNALED;
 	fastreg_wr.wr.fast_reg.iova_start = (unsigned long)frmr->kva;
 	fastreg_wr.wr.fast_reg.page_list = frmr->page_list;
 	fastreg_wr.wr.fast_reg.page_list_len = frmr->page_list_len;
 	fastreg_wr.wr.fast_reg.page_shift = PAGE_SHIFT;
 	fastreg_wr.wr.fast_reg.length = frmr->map_len;
 	fastreg_wr.wr.fast_reg.access_flags = frmr->access_flags;
 	fastreg_wr.wr.fast_reg.rkey = frmr->mr->lkey;
 	fastreg_wr.next = &read_wr;

 	/* Prepare RDMA_READ */
 	memset(&read_wr, 0, sizeof(read_wr));
 	read_wr.send_flags = IB_SEND_SIGNALED;
 	read_wr.wr.rdma.rkey = rs_handle;
 	read_wr.wr.rdma.remote_addr = rs_offset;
 	read_wr.sg_list = ctxt->sge;
 	read_wr.num_sge = 1;
 	if (xprt->sc_dev_caps & SVCRDMA_DEVCAP_READ_W_INV) {
 		read_wr.opcode = IB_WR_RDMA_READ_WITH_INV;
 		read_wr.wr_id = (unsigned long)ctxt;
 		read_wr.ex.invalidate_rkey = ctxt->frmr->mr->lkey;
 	} else {
 		read_wr.opcode = IB_WR_RDMA_READ;
 		read_wr.next = &inv_wr;
 		/* Prepare invalidate */
 		memset(&inv_wr, 0, sizeof(inv_wr));
 		inv_wr.wr_id = (unsigned long)ctxt;
 		inv_wr.opcode = IB_WR_LOCAL_INV;
 		inv_wr.send_flags = IB_SEND_SIGNALED | IB_SEND_FENCE;
 		inv_wr.ex.invalidate_rkey = frmr->mr->lkey;
 	}
 	ctxt->wr_op = read_wr.opcode;

 	/* Post the chain */
 	ret = svc_rdma_send(xprt, &fastreg_wr);
 	if (ret) {
 		pr_err("svcrdma: Error %d posting RDMA_READ\n", ret);
 		set_bit(XPT_CLOSE, &xprt->sc_xprt.xpt_flags);
 		goto err;
 	}

 	/* return current location in page array */
 	*page_no = pg_no;
 	*page_offset = pg_off;
 	ret = read;
 	atomic_inc(&rdma_stat_read);
 	return ret;
  err:
 	svc_rdma_unmap_dma(ctxt);
 	svc_rdma_put_context(ctxt, 0);
 	svc_rdma_put_frmr(xprt, frmr);
 	return ret;
 }



